INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 98, 'proposito', 'Vigilar, inspeccionar y controlar la prestación de los servicios de salud para que la población goce de una mejor calidad de vida, a través de estrategias que permitan garantizar el propósito de vigilancia y control. Coordinar el manejo integral de los programas sociales de la entidad de conformidad con lo establecido en el plan de desarrollo municipal y las políticas públicas del nivel central.', 140 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=98 AND seccion='proposito');  -- FICHA 92
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 98, 'funciones', '["Fijar las políticas de la Secretaría, acorde con el Plan de Desarrollo Municipal a fin de dar cumplimiento a la misión institucional.", "Establecer las estrategias y el plan de acción a seguir para el logro de las políticas, programas y proyectos consagrados en el Plan de Desarrollo Municipal y liderar su ejecución.", "Supervisar la ejecución del presupuesto que corresponda a la Secretaría para controlar el gasto.", "Asistir ante el Concejo Municipal, juntas, comités y otros estamentos cuando le sean delegados por el señor Alcalde para que lo represente.", "Rendir informes periódicos al Alcalde y demás instituciones que lo requieran sobre el desarrollo y ejecución de los proyectos relacionados con las actividades de la Secretaría y/o la Administración central, para su correspondiente análisis, evaluación, seguimiento y toma de decisiones.", "Coordinar con la secretaría de Planeación, los planes y programas de la Secretaría, tanto en su etapa de elaboración y formulación, para que sean inscritos en el Banco de Programas y Proyectos de Inversión Municipal.", "Gestionar ante las diferentes dependencias de la entidad o con organismos del orden Municipal, Departamental, subregional, Nacional e internacional, la obtención de los recursos necesarios, para asegurar el oportuno cumplimiento de los planes, programas y proyectos establecidos en el Plan de Desarrollo.", "Planear, dirigir y controlar el cumplimiento de los objetivos y estrategias que apunten al cumplimiento de la misión del organismo en concordancia con los planes de desarrollo y las políticas trazadas.", "Dirigir la formulación y fijación de políticas, adoptar los planes generales relacionados con el organismo y velar por el cumplimiento de los términos y condiciones establecidos para su ejecución.", "Implementar las políticas sociales y el desarrollo de la comunidad trazadas por el programa de gobierno y el Plan de Desarrollo Municipal, garantizando la inversión Social del Municipio, conjuntamente con la proveniente del sector estatal no municipal y el privado.", "Adelantar dentro del marco de las funciones propias del organismo las gestiones necesarias para asegurar el oportuno cumplimiento de los planes, programas y proyectos.", "Dirigir, coordinar y controlar la ejecución de planes, programas y proyectos dirigidos a los grupos de población más vulnerables a la desnutrición y en especial a los establecimientos educativos, para asegurar el mejoramiento nutricional.", "Realizar administración y puesta en marcha de cada uno de los programas sociales actualmente liderados y que se llegaren liderar por parte de la administración municipal.", "Velando siempre por que los mismos contribuyan de manera efectiva al mejoramiento de las condiciones de vida de la población en condiciones de vulnerabilidad.", "Investigar, diagnosticar y definir las variables sociales que afectan el normal funcionamiento de grupos poblacionales como menores en situación irregular, familia, discapacitados, indigentes, desplazados, tercera edad, mujeres cabeza de familia y madres comunitarias, población LGTBI.", "Gestionar ante las diferentes dependencias de la entidad o con organismos del orden Municipal, Departamental, subregional, Nacional e internacional, la obtención de recursos económicos, técnicos, tecnológicos y humanos, a fin de ejecutar políticas, programas y proyectos en materia de bienestar social, que permitan ampliar y mejorar la prestación de los servicios.", "Establecer las estrategias y el plan de acción a seguir, para el logro de las políticas, programas y proyectos consagrados en el Plan de Desarrollo Municipal y liderar su ejecución en relación con la población vulnerable.", "Solicitar y suministrar a las respectivas entidades u organismos Municipales, la información que sea necesaria para la actualización y el correcto funcionamiento del Sistema de Información de la Dependencia en relación con la población vulnerable.", "Supervisar la ejecución del presupuesto que corresponda a la secretaría para controlar el gasto.", "Proponer a quien corresponda, la realización de programas de capacitación e investigación según las necesidades determinadas en el plan de desarrollo Municipal e institucional en relación con los grupos de población vulnerable.", "Verificar que los recursos provenientes de las diferentes fuentes de financiamiento, se administren adecuadamente y se utilicen en función de las prioridades establecidas en el Plan de Desarrollo Municipal.", "Evaluar periódicamente el funcionamiento de la SECRETARÌA y aplicar los correctivos cuando fuese necesario.", "Atender y canalizar las quejas que los usuarios presenten sobre la eficiencia en la prestación de los servicios en cualquiera de los programas liderados por la entidad y vigilar que se tomen los correctivos del caso.", "Presentar iniciativas de proyectos de acuerdos, planes y programas en asuntos relacionados con la dependencia, para mejorar la calidad en la prestación del servicio.", "Asistir ante el Concejo Municipal, juntas, comités y otros estamentos, cuando le sean delegados por el señor Alcalde para que lo represente.", "Rendir informes periódicos al Alcalde, Concejo Municipal y demás instituciones que lo requieran sobre el desarrollo y ejecución de los proyectos relacionados con las actividades de la secretaría de Inclusión Social, para su correspondiente análisis, evaluación, seguimiento y toma de decisiones.", "Adoptar las acciones necesarias para garantizar el sistema de gestión de la calidad y el control interno dentro de la dependencia."]', 141 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=98 AND seccion='funciones');  -- FICHA 92
