INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 108, 'proposito', 'Representar, a la administración Municipal ante la comunidad en los asuntos de su competencia, para asegurar el cumplimiento de la constitución, la ley, ordenanzas, acuerdos del concejo y actos del Alcalde en todo el territorio y el mantenimiento del orden público interno. Velar, por el cumplimiento de las normas de sana convivencia para garantizar la seguridad, comodidad de los habitantes y preservación de un ambiente sano y protección del bien común.', 140 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=108 AND seccion='proposito');  -- FICHA 10
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 108, 'funciones', '["Hacer cumplir las disposiciones legales que regulen el medio ambiente, la fauna y flora, para velar por la preservación y mantenimiento de los recursos naturales y del medio ambiente.", "Cumplir con las órdenes y comisiones que le sean encomendadas por los Jueces, Fiscales y auxiliares de exhortos, para apoyar la recta y pronta administración de justicia.", "Efectuar Inspecciones oculares, de acuerdo a instrucciones impartidas por el superior inmediato, para verificar el cumplimiento de los requisitos legales establecidos con relación a los establecimientos abiertos al público, rendir los informes correspondientes para la actualización de la información y toma de decisiones oportunas.", "Presentar, informes de gestión ante el Secretario de Gobierno para hacer seguimiento y evaluación a los objetivos trazados por la dependencia.", "Cumplir con las atribuciones que señalan la constitución política, el Código Nacional de policía y convivencia ciudadana y demás normas que regulan la materia, de forma oportuna y conforme con los lineamientos y orientaciones municipales en la materia.", "Adelantar conciliaciones para la solución de conflictos de convivencia, cuando sea procedente, en el marco de la norma vigente.", "Conocer de los comportamientos contrarios a la convivencia en materia de seguridad, tranquilidad, ambiente y recursos naturales, derecho de reunión, protección a los bienes y privacidad, actividad económica, urbanismo, espacio público y libertad de circulación, de conformidad con la normatividad vigente.", "Ejecutar la orden de restitución, en caso de tierras comunales, de acuerdo con la con la normatividad vigente y los procesos que se señalen para tal fin.", "Conocer en única instancia, de la aplicación de las siguientes medidas correctivas:", "Reparación de daños materiales de muebles o inmuebles expulsión de domicilio, prohibición de ingreso a actividad que involucra aglomeraciones de público complejas o no complejas, decomiso.", "Conocer en primera instancia de las siguientes medidas correctivas:", "Suspensión de construcción o demolición de obra, construcción, cerramiento, reparación o mantenimiento de inmueble, reparación de daños materiales por perturbación a la posesión y tenencia de inmuebles, restitución y protección de bienes inmuebles, diferentes a los descritos en el numeral 17 del artículo 205, restablecimiento del derecho de servidumbre y reparación de daños materiales, remoción de bienes, en las infracciones urbanísticas, multas y suspensión definitiva de actividad.", "Atender los requerimientos que sean radicados para su atención como autoridad de policía de forma oportuna, conforme con los lineamientos y orientaciones municipales en la materia y el marco normativo vigente.", "Adelantar las acciones de control y/o operativos en materia de seguridad, tranquilidad, ambiente y recursos naturales, derecho de reunión, actividad económica, urbanismo, espacio público y libertad de circulación, de conformidad con la normatividad vigente.", "Adelantar las acciones que promuevan la convivencia ciudadana de manera conjunta y coordinada con las demás autoridades administrativas y de policía que intervengan en el proceso, conforme con los lineamientos, orientaciones en la materia y normatividad vigente.", "Presentar los informes de gestión a que haya lugar y atender los distintos requerimientos que presenten las distintas autoridades en temas de competencia de conformidad con los lineamientos y orientaciones municipales en la materia y la normatividad vigente.", "Verificar que las comunicaciones, citaciones y notificaciones de los asuntos policivos que se tramiten en su Despacho estén conformes con los procesos y procedimientos definidos.", "Desempeñar las demás funciones que le sean asignadas por el jefe Inmediatito y que correspondan y que correspondan a la naturaleza del empleo Y las demás que le asigne el jefe inmediato."]', 141 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=108 AND seccion='funciones');  -- FICHA 10
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 108, 'contribuciones', '["Dentro del municipio se cumple la constitución, la ley, ordenanzas, acuerdos, y actos del alcalde.", "Se cumplen las normas del CODIGO NACIONAL DE POLICIA.", "Las solicitudes, quejas e inquietudes jurídicas que tiene la ciudadanía, atendidas amables y oportunamente, a través de las audiencias judiciales donde se orienta y/o resuelve la situación presentada.", "Las denuncias recepcionadas, dejando registro de los hechos manifestados por el denunciante a través de actas que deben ser remitidas a las autoridades competentes para su solución.", "Los procesos policivos de lanzamiento relacionados con: ocupaciones de hecho, perturbaciones a la posesión, amparo al domicilio, amparo a la servidumbre, recuperación del espacio público y demolición por amenaza de ruina; ejecutados dándole el respectivo trámite de conformidad con las normas policivas y demás normas concordantes.", "Los recursos físicos que se utilizan en el área o dependencia, para la realización de las labores propias de su cargo, racionalizados, de acuerdo a las normas administrativas municipales.", "Las inconsistencias o anomalías encontradas producto de la realización de las actividades propias del cargo, así como las relacionadas con verificaciones o controles propios de los procesos, reportadas al jefe inmediato en forma oportuna."]', 142 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=108 AND seccion='contribuciones');  -- FICHA 10
